// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// Primary inherits movers from VaultLogic via using-for. Sibling Morpho must not leak.
contract VaultV3 {
    using VaultLogic for address;
    function deposit(uint256 amount) external { address(0).pull(msg.sender, amount); }
    function withdraw(uint256 amount) external { amount; }
    function convertToShares(uint256 assets) public view returns (uint256) { return assets; }
    function convertToAssets(uint256 shares) public view returns (uint256) { return shares; }
    function totalAssets() public view returns (uint256) { return 1; }
}

lib/VaultLogic.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;
interface IERC20L { function transferFrom(address, address, uint256) external returns (bool); }
library VaultLogic {
    function pull(address token, address from, uint256 amount) internal {
        IERC20L(token).transferFrom(from, address(this), amount);
    }
    function harvest(address token, uint256 amount) external {
        IERC20L(token).transferFrom(msg.sender, address(this), amount);
    }
}

